def show(f):
    if isinstance(f, str):
        return f
    if f[0] == "not":
        return "¬" + show(f[1])
    if f[0] == "and":
        return "(" + " ∧ ".join(show(g) for g in f[1:]) + ")"
    return "(" + show(f[1]) + " → " + show(f[2]) + ")"


